begin;

insert into public.flashcard_sets (teacher_id, name, category, level, description, cards)
select
  t.id,
  'Từ vựng về chủ đề biển',
  'Từ Vựng Theo Chủ Đề',
  'Cơ bản',
  '',
  '[{"front":"Sea","back":"Biển"},{"front":"Ocean","back":"Đại dương"},{"front":"Wave","back":"Sóng"},{"front":"Island","back":"Hòn đảo"},{"front":"Harbor","back":"Cảng biển"},{"front":"Lighthouse","back":"Hải đăng"},{"front":"Submarine","back":"Tàu ngầm"},{"front":"Ship","back":"Tàu thuỷ"},{"front":"Boat","back":"Thuyền"},{"front":"Captain","back":"Thuyền trưởng"},{"front":"Fisherman","back":"Ngư dân"},{"front":"Lifeguard","back":"Người cứu hộ"},{"front":"Seashore","back":"Bờ biển"},{"front":"Beach","back":"Bãi biển"},{"front":"Coast","back":"Bờ biển"},{"front":"Seagull","back":"Mòng biển"},{"front":"Whale","back":"Cá voi"},{"front":"Shark","back":"Cá mập"},{"front":"Dolphin","back":"Cá heo"},{"front":"Octopus","back":"Bạch tuộc"},{"front":"Fish","back":"Cá"},{"front":"Jellyfish","back":"Sứa"},{"front":"Sea horse","back":"Cá ngựa"},{"front":"Seaweed","back":"Rong biển"},{"front":"Coral","back":"San hô"},{"front":"Coral reef","back":"Rạn san hô"},{"front":"Shellfish","back":"Động vật có vỏ"},{"front":"Clam","back":"Nghêu"},{"front":"Starfish","back":"Sao biển"},{"front":"Seal","back":"Hải cẩu"},{"front":"Turtle","back":"Rùa biển"},{"front":"Crab","back":"Cua"}]'::jsonb
from public.users t
where t.id = (select id from public.users order by created_at asc nulls last limit 1)
  and not exists (
    select 1 from public.flashcard_sets s
    where s.name = 'Từ vựng về chủ đề biển' and s.category = 'Từ Vựng Theo Chủ Đề'
  );

